                Map.of("type", "captured", "paymentId", "pay_7782", "amountMinor", "12.50"),
                Map.of("type", "refunded", "paymentId", "7781", "amountMinor", "500"),
                Map.of("type", "refunded", "paymentId", "pay_7781", "amountMinor", "-500"),
